add("en","B1","Eylemler","emerge","ortaya çıkmak","verb","New problems emerged.","Yeni sorunlar ortaya çıktı.");
add("en","B1","Eylemler","generate","üretmek / yaratmak","verb","This generates a lot of income.","Bu çok gelir üretiyor.");
add("en","B1","Eylemler","implement","uygulamaya koymak","verb","We will implement the plan.","Planı uygulamaya koyacağız.");
add("en","B1","Eylemler","indicate","belirtmek / göstermek","verb","The results indicate progress.","Sonuçlar ilerlemeyi gösteriyor.");
add("en","B1","Eylemler","obtain","elde etmek","verb","He obtained a good result.","İyi bir sonuç elde etti.");
add("en","B1","Eylemler","occur","meydana gelmek / olmak","verb","The accident occurred at night.","Kaza gece meydana geldi.");
add("en","B1","Eylemler","proceed","devam etmek / ilerlemek","verb","Let's proceed with the plan.","Planla devam edelim.");
add("en","B1","Eylemler","reveal","ortaya çıkarmak / ifşa etmek","verb","The study reveals new facts.","Çalışma yeni gerçekleri ortaya çıkarıyor.");
add("en","B1","Eylemler","specify","belirtmek / özellik belirtmek","verb","Please specify the date.","Lütfen tarihi belirtin.");
add("en","B1","Eylemler","tend to","eğiliminde olmak","verb","People tend to forget.","İnsanlar unutma eğilimindedir.");
add("en","B1","Sıfatlar","insignificant","önemsiz","adjective","The difference is insignificant.","Fark önemsiz.");
add("en","B1","Sıfatlar","relevant","ilgili / alakalı","adjective","This information is relevant.","Bu bilgi ilgili.");
add("en","B1","Sıfatlar","irrelevant","ilgisiz / alakasız","adjective","That's irrelevant to the topic.","Bu konuyla alakasız.");
add("en","B1","Sıfatlar","inadequate","yetersiz","adjective","The training was inadequate.","Eğitim yetersizdi.");
add("en","B1","Sıfatlar","distinct","farklı / belirgin","adjective","These are two distinct issues.","Bunlar iki farklı konu.");
add("en","B1","Sıfatlar","identical","özdeş / aynı","adjective","The twins are identical.","İkizler özdeş.");
add("en","B1","Sıfatlar","diverse","çeşitli / farklı","adjective","The city has a diverse population.","Şehrin çeşitli bir nüfusu var.");
add("en","B1","Sıfatlar","uniform (adjective)","tek tip / homojen","adjective","The results were uniform.","Sonuçlar homojendi.");
add("en","B1","Sıfatlar","gradual","kademeli","adjective","There was a gradual change.","Kademeli bir değişim oldu.");
add("en","B1","Sıfatlar","sudden","ani","adjective","It was a sudden decision.","Bu ani bir karardı.");
add("en","B1","Sıfatlar","legitimate","meşru / geçerli","adjective","That's a legitimate concern.","Bu geçerli bir endişe.");
add("en","B1","Bağlaçlar","in addition to","buna ek olarak","phrase","In addition to this, the price is good.","Buna ek olarak, fiyat da iyi.");
add("en","B1","Bağlaçlar","based on this","buna dayanarak","phrase","Based on this, we made a decision.","Buna dayanarak bir karar aldık.");
add("en","B1","Bağlaçlar","despite this","buna rağmen","phrase","Despite this, he continued.","Buna rağmen devam etti.");
add("en","A1","Sesler ve Duyular","taste (noun)","tat / lezzet","noun","This has a strange taste.","Bunun tuhaf bir tadı var.");
add("en","A1","Sesler ve Duyular","smell (noun)","koku","noun","There's a nice smell here.","Burada güzel bir koku var.");
add("en","A1","Sesler ve Duyular","touch (noun)","dokunuş","noun","Her touch was gentle.","Onun dokunuşu nazikti.");
add("en","A1","Sesler ve Duyular","sight","görme (duyu) / manzara","noun","His sight is weak.","Görmesi zayıf.");
add("en","A1","Sesler ve Duyular","hearing (noun)","işitme (duyu)","noun","Her hearing is excellent.","İşitmesi mükemmel.");
add("en","A1","Fiiller","spill","dökmek / dökülmek","verb","I spilled my coffee.","Kahvemi döktüm.");
add("en","A1","Fiiller","pour","dökmek (sıvı)","verb","Pour the water into the glass.","Suyu bardağa dök.");
add("en","A1","Fiiller","squeeze","sıkmak","verb","Squeeze the lemon.","Limonu sık.");
add("en","A1","Fiiller","grind","öğütmek","verb","Grind the coffee beans.","Kahve çekirdeklerini öğüt.");
add("en","A1","Fiiller","slice (verb)","dilimlemek","verb","Slice the bread.","Ekmeği dilimle.");
